def wrap(text, width, indent=""):
    """Wrap `text` to lines of at most `width` characters. See TASK.md."""
    if isinstance(width, bool) or not isinstance(width, int) or width < 1:
        raise ValueError("width must be an int of at least 1")
    if not isinstance(indent, str) or len(indent) >= width:
        raise ValueError("indent must be a str shorter than width")

    lines = []
    for paragraph in text.split("\n"):
        lines.extend(_wrap_paragraph(paragraph.split(), width, indent))
    return lines


def _wrap_paragraph(words, width, indent):
    """Wrap the words of one paragraph. Rules 2-5 of TASK.md."""
    if not words:
        return [""]

    lines = []
    cur = None  # content of the line being built (without its indent)

    def prefix():
        # The first line of a paragraph has no indent; every later one does.
        return indent if lines else ""

    for word in words:
        while True:
            cap = width - len(prefix())
            if cur is None:
                if len(word) <= cap:
                    cur = word
                    break
                # Does not fit on an empty line: fill it, carry the rest on.
                lines.append(prefix() + word[:cap])
                word = word[cap:]
                continue
            if len(cur) + 1 + len(word) <= cap:
                cur += " " + word
                break
            # Does not fit on the current line: start a new one.
            lines.append(prefix() + cur)
            cur = None

    if cur is not None:
        lines.append(prefix() + cur)
    return lines
